package ec.edu.ucuenca.mda.vuelos.service;
import ec.edu.ucuenca.mda.vuelos.domain.*;
import ec.edu.ucuenca.mda.vuelos.dto.*;
import ec.edu.ucuenca.mda.vuelos.repository.*;
import ec.edu.ucuenca.mda.vuelos.support.*;
import java.time.*;
import java.util.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
@Transactional(readOnly=true)
public class BoletoService {
    private final BoletoRepository repository;
    private final VueloRepository vueloRepository;
    private final ReservaRepository reservaRepository;
    private final Clock clock;
    public BoletoService(BoletoRepository repository, VueloRepository vueloRepository, ReservaRepository reservaRepository, Clock clock) {
        this.repository = repository;
        this.vueloRepository = vueloRepository;
        this.reservaRepository = reservaRepository;
        this.clock = clock;
    }
    private BoletoResponse response(Boleto value) {
        return BoletoResponse.from(value);
    }
    public BoletoResponse get(Long id) { return response(repository.findById(id).orElseThrow(() -> BusinessException.notFound("Boleto no encontrado"))); }
    public List<BoletoResponse> list(String numero) {
        return (numero == null ? repository.findAll(Sort.by("id")) : repository.findByNumero(numero.trim().toUpperCase(Locale.ROOT))).stream().map(this::response).toList();
    }
    @Transactional
    public BoletoResponse issue(Long reservaId) {
        Long flightId = reservaRepository.findVueloIdById(reservaId).orElseThrow(() -> BusinessException.notFound("Reserva no encontrada"));
        Vuelo vuelo = vueloRepository.lockById(flightId).orElseThrow(() -> BusinessException.notFound("Vuelo no encontrado"));
        Reserva reserva = reservaRepository.lockById(reservaId).orElseThrow(() -> BusinessException.notFound("Reserva no encontrada"));
        BusinessException.check(reserva.getEstado() == EstadoReserva.CONFIRMADA, "RN-07", "La reserva debe estar confirmada");
        BusinessException.check(vuelo.getSalida().isAfter(OffsetDateTime.now(clock)), "RN-12", "No se puede emitir despues de la salida");
        Optional<Boleto> existing = repository.findByReserva_Id(reservaId);
        if (existing.isPresent()) return response(existing.get());
        Boleto value = new Boleto();
        value.setNumero("BOL-" + UUID.randomUUID().toString().toUpperCase(Locale.ROOT));
        value.setEmitidoEn(OffsetDateTime.now(clock)); value.setReserva(reserva);
        return response(repository.saveAndFlush(value));
    }
}
